{
  "policy": "latest-stable",
  "absorbedVersion": "10.0.7",
  "source": {
    "kind": "pattern",
    "url": "https://www.kicad.org/blog/categories/Release-Notes/",
    "pattern": "/blog/\\d{4}/\\d{2}/KiCad-(\\d+\\.\\d+\\.\\d+)-Release/"
  },
  "releaseNotes": "https://www.kicad.org/blog/2026/10/KiCad-10.0.7-Release/",
  "scope": "Target KiCad 10.0.7 (latest stable, 2026-10-07) kicad-cli: saved two-copper-layer board statistics, native DRC JSON with authored maximum counts, decimal absolute Excellon drill export; independent host board reader, statistics/DRC/drill-hit cross-checks and captured-input mutation checks. No board authoring, zone refill, schematic parity, Gerber/STEP/position outputs, slots, blind/buried vias or drill maps.",
  "evidence": [
    "verification/2026-10-16-kicad-completion.md"
  ],
  "acceptance": [
    "Run tools/qualify_kicad.py with the target kicad-cli; require the baseline/variant fixtures to verify, the clearance and open-net fixtures to fail with DRC_VIOLATIONS matching host predictions, tamper/mutation probes to fail, and native adaptor conformance to pass."
  ]
}
